"""Benign carriers and hard negatives generated by gpt-5.6-luna (batched, cached, budget-guarded).

Every response is stored in an exact-request cache, so re-running with the same seed reproduces the same carriers
without any API call. Output: ``data/generated/carriers_llm.jsonl``.

Usage:
    python -m pidefense.data.carriers_llm --max-usd 1.0
"""

from __future__ import annotations

import argparse
import asyncio
import hashlib
import json
import logging
import random
from dataclasses import asdict, dataclass
from pathlib import Path

from pidefense.config import REPO_ROOT
from pidefense.llm import AzureChatClient, ResponseCache
from pidefense.logging_utils import setup_logging

logger = logging.getLogger(__name__)

GENERATED_DIR = REPO_ROOT / "data" / "generated"
CACHE_PATH = GENERATED_DIR / "llm_cache.jsonl"
OUTPUT_PATH = GENERATED_DIR / "carriers_llm.jsonl"
ITEMS_PER_CALL = 10

CARRIER_KINDS: dict[str, str] = {
    "email": "emails as returned by an email-reading tool; each starts with 'From:', 'To:', 'Subject:' lines, "
    "then a blank line and the body",
    "web_page": "web page text extracts (a headline followed by paragraphs) as returned by a web-fetch tool",
    "document": "internal documents or notes (memos, short reports, meeting notes) as returned by a file-reading tool",
    "product_reviews": "customer product review sections, each with 2-3 short reviews including star ratings",
    "support_ticket": "customer support tickets or chat transcripts between a customer and an agent",
    "calendar_invite": "calendar invitation texts with title, time, location, attendees and a description",
    "news": "short news articles",
}
HARD_NEGATIVE_KINDS: dict[str, str] = {
    "how_to": "step-by-step how-to guides written directly to the reader in the imperative mood",
    "it_runbook": "IT runbooks or troubleshooting guides that tell the reader which commands to run and what to "
    "ignore",
    "request_email": "emails that ask the recipient to do things, e.g. forward a message to the team, ignore an "
    "earlier email, update a document, transfer a payment or send information to a colleague",
    "recipe": "cooking recipes with ingredient lists and instructions",
    "policy": "company policy texts with rules that employees must follow",
    "assistant_docs": "product documentation explaining what an AI assistant feature does and how users configure it",
    "security_awareness": "security awareness texts warning about phishing and telling readers what never to do",
    "meeting_actions": "meeting notes with action items and instructions assigned to named people",
}
TOPICS = [
    "finance and accounting",
    "human resources",
    "business travel",
    "software engineering",
    "healthcare appointments",
    "real estate",
    "university courses",
    "online retail orders",
    "logistics and shipping",
    "marketing campaigns",
    "legal contracts",
    "customer support",
    "local sports club",
    "restaurants and food delivery",
    "IT outage",
    "conference planning",
    "scientific research",
    "public administration",
    "insurance claims",
    "energy bills",
    "car maintenance",
    "gardening",
    "home renovation",
    "product launch",
    "school events",
    "personal banking",
    "cloud infrastructure",
    "event tickets",
    "pet care",
    "fitness and health",
    "museum exhibitions",
    "public transport",
    "charity fundraising",
    "photography",
    "tax returns",
    "hiring and interviews",
    "data privacy",
    "manufacturing",
    "agriculture",
    "tourism",
]
STYLES = [
    "formal corporate",
    "casual and friendly",
    "terse automated notification",
    "newsletter",
    "personal and informal",
    "technical",
    "bureaucratic",
    "enthusiastic marketing",
]
LANG_NAMES = {"en": "English", "hu": "Hungarian (natural, native Hungarian, not a translation)"}
SYSTEM_PROMPT = "You generate realistic synthetic text data for a machine-learning dataset. Output only valid JSON."


@dataclass(frozen=True)
class GenerationJob:
    """One batched generation request."""

    kind: str
    description: str
    lang: str
    topic: str
    style: str
    hard_negative: bool
    index: int

    def prompt(self) -> str:
        """User prompt for this job."""
        return (
            f"Write {ITEMS_PER_CALL} different realistic {self.description}. Language: {LANG_NAMES[self.lang]}. "
            f"Topic area: {self.topic}. Tone: {self.style}. Each item should be 40-120 words. Vary names, numbers, "
            f"details and structure; use fictional people and companies. "
            f'Return a JSON object {{"items": [...]}} containing exactly {ITEMS_PER_CALL} strings.'
        )


@dataclass(frozen=True)
class LLMCarrier:
    """One generated text."""

    carrier_id: str
    carrier_type: str
    lang: str
    topic: str
    style: str
    hard_negative: bool
    text: str
    generator: str


def plan_jobs(calls: dict[tuple[str, bool], int], seed: int) -> list[GenerationJob]:
    """Spread the requested number of calls per (lang, hard_negative) evenly over kinds, topics and styles.

    Each job depends only on (seed, lang, hard_negative, index), so a smaller run is a prefix of a larger one and
    its cached responses are reused.
    """
    jobs: list[GenerationJob] = []
    for (lang, hard_negative), n_calls in sorted(calls.items()):
        kinds = HARD_NEGATIVE_KINDS if hard_negative else CARRIER_KINDS
        names = sorted(kinds)
        for index in range(n_calls):
            rng = random.Random(f"{seed}-{lang}-{hard_negative}-{index}")
            kind = names[index % len(names)]
            jobs.append(
                GenerationJob(
                    kind=kind,
                    description=kinds[kind],
                    lang=lang,
                    topic=rng.choice(TOPICS),
                    style=rng.choice(STYLES),
                    hard_negative=hard_negative,
                    index=index,
                )
            )
    return jobs


def _parse_items(content: str | None) -> list[str]:
    if not content:
        return []
    try:
        data = json.loads(content)
    except json.JSONDecodeError:
        logger.warning("Unparseable generation output (%d chars)", len(content))
        return []
    items = data.get("items") if isinstance(data, dict) else None
    return [item.strip() for item in items or [] if isinstance(item, str) and len(item.split()) >= 15]


async def run_jobs(jobs: list[GenerationJob], max_usd: float, concurrency: int = 8) -> list[LLMCarrier]:
    """Execute the jobs; stop scheduling new paid calls once this run has spent ``max_usd``."""
    client = AzureChatClient(cache=ResponseCache(CACHE_PATH))
    start_total = client.ledger.total_usd
    semaphore = asyncio.Semaphore(concurrency)
    carriers: list[LLMCarrier] = []
    skipped = 0

    async def worker(job: GenerationJob) -> None:
        nonlocal skipped
        async with semaphore:
            if client.ledger.total_usd - start_total >= max_usd:
                skipped += 1
                return
            response = await client.chat(
                [{"role": "system", "content": SYSTEM_PROMPT}, {"role": "user", "content": job.prompt()}],
                purpose="data-generation",
                reasoning_effort="none",
                response_format={"type": "json_object"},
                max_completion_tokens=4000,
            )
        if response.blocked_by_provider:
            logger.warning("Content filter blocked job %s/%s/%d", job.kind, job.lang, job.index)
            return
        for position, text in enumerate(_parse_items(response.content)):
            digest = hashlib.sha1(f"{job.kind}|{job.lang}|{job.index}|{position}|{text}".encode()).hexdigest()[:12]
            carriers.append(
                LLMCarrier(
                    carrier_id=f"llm-{digest}",
                    carrier_type=job.kind,
                    lang=job.lang,
                    topic=job.topic,
                    style=job.style,
                    hard_negative=job.hard_negative,
                    text=text,
                    generator=f"llm:{client.settings.deployment}",
                )
            )

    try:
        await asyncio.gather(*(worker(job) for job in jobs))
    finally:
        await client.aclose()
    spent = client.ledger.total_usd - start_total
    logger.info(
        "Generated %d texts from %d jobs (%d skipped by budget); spent $%.4f", len(carriers), len(jobs), skipped, spent
    )
    return carriers


def save(carriers: list[LLMCarrier], path: Path = OUTPUT_PATH) -> None:
    """Write carriers as JSONL, sorted by id for stable diffs."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for carrier in sorted(carriers, key=lambda c: c.carrier_id):
            handle.write(json.dumps(asdict(carrier), ensure_ascii=False) + "\n")
    logger.info("Wrote %s", path)


def load(path: Path = OUTPUT_PATH) -> list[LLMCarrier]:
    """Read carriers written by ``save``."""
    with path.open(encoding="utf-8") as handle:
        return [LLMCarrier(**json.loads(line)) for line in handle if line.strip()]


def main() -> None:
    """CLI entry point."""
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--max-usd", type=float, default=1.0, help="spending limit for this run")
    parser.add_argument("--seed", type=int, default=7)
    parser.add_argument("--scale", type=float, default=1.0, help="multiply the default number of calls")
    args = parser.parse_args()
    setup_logging()
    base_calls = {("en", False): 144, ("hu", False): 96, ("en", True): 72, ("hu", True): 48}
    calls = {key: max(1, round(value * args.scale)) for key, value in base_calls.items()}
    jobs = plan_jobs(calls, args.seed)
    logger.info("Planned %d generation calls (%d texts max)", len(jobs), len(jobs) * ITEMS_PER_CALL)
    carriers = asyncio.run(run_jobs(jobs, args.max_usd))
    save(carriers)


if __name__ == "__main__":
    main()
